    void bothFiltersMustHold() {
        assertTrue(shows(new CustomerFilter("ada", Set.of(CustomerStatus.PENDING)), ADA));
        assertFalse(shows(new CustomerFilter("ada", Set.of(CustomerStatus.CLOSED)), ADA));
        assertFalse(shows(new CustomerFilter("jarno", Set.of(CustomerStatus.PENDING)), ADA));
    }
}
