}", "newString": "    /**
     * Writes the filter as a query string, such as {@code name=vir&status=ACTIVE,CLOSED}.
     * An empty filter writes nothing. The commas are left literal: the address reads
     * better that way, and {@link QueryParameters} would escape them.
     */
    static String toQueryString(CustomerFilter filter) {
        List<String> parts = new ArrayList<>();
        if (!filter.name().isBlank()) {
            parts.add(NAME_PARAMETER + "=" + encode(filter.name()));
        }
        // Declaration order, so the same filter always gives the same address.
        String statuses = Arrays.stream(CustomerStatus.values())
                .filter(filter.statuses()::contains)
                .map(Enum::name)
                .collect(Collectors.joining(","));
        if (!statuses.isEmpty()) {
            parts.add(STATUS_PARAMETER + "=" + statuses);
        }
        return String.join("&", parts);
    }

    private static String encode(String value) {
        return URLEncoder.encode(value, StandardCharsets.UTF_8).replace("+", "%20");
    }
