+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.function.Predicate;
+import java.util.regex.Pattern;
+
+/**
+ * Narrows the customer list by name and by status. A customer is shown only when
+ * it satisfies both parts.
+ *
+ * @param name     text to match against names: it is split on whitespace, and every
+ *                 term must appear in the first name or the last name. Case and
+ *                 accents are ignored. Blank matches every customer.
+ * @param statuses statuses to show; empty shows every status
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    /** Matches every customer. */
+    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());
+
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
+    private static final Pattern COMBINING_MARKS = Pattern.compile("\\p{M}+");
+
+    public CustomerFilter {
+        name = (name == null) ? "" : name;
+        statuses = (statuses == null) ? Set.of() : Set.copyOf(statuses);
+    }
+
+    /**
+     * Returns a predicate that accepts the customers this filter shows. The name
+     * terms are worked out once, so the predicate is cheap to apply to every row.
+     */
+    public Predicate<Customer> asPredicate() {
+        List<String> terms = nameTerms(name);
+        return customer -> matchesStatus(customer) && matchesName(customer, terms);
+    }
+
+    private boolean matchesStatus(Customer customer) {
+        return statuses.isEmpty() || statuses.contains(customer.status());
+    }
+
+    private static boolean matchesName(Customer customer, List<String> terms) {
+        String firstName = fold(customer.firstName());
+        String lastName = fold(customer.lastName());
+        return terms.stream().allMatch(term -> firstName.contains(term) || lastName.contains(term));
+    }
+
+    private static List<String> nameTerms(String text) {
+        return Arrays.stream(WHITESPACE.split(fold(text)))
+                .filter(term -> !term.isEmpty())
+                .toList();
+    }
+
+    /** Strips accents and ignores case, so that {@code Mäkinen} folds to {@code makinen}. */
+    private static String fold(String text) {
+        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD);
+        return COMBINING_MARKS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
+}
