@@ -0,0 +1,73 @@
+package com.example.customers.domain;
+
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.util.Set;
+
+import org.junit.jupiter.api.Test;
+
+class CustomerFilterTest {
+
+    private static final Customer MAKINEN = new Customer(
+            1009, "Jarno", "Mäkinen", "jarno@example.com", "Netherlands", CustomerStatus.ACTIVE);
+    private static final Customer ADA = new Customer(
+            1000, "Ada", "Aaltonen", "ada@example.com", "Finland", CustomerStatus.PENDING);
+    private static final Customer JOSEPHINE = new Customer(
+            1035, "Joséphine", "Aaltonen", "josephine@example.com", "Portugal", CustomerStatus.CLOSED);
+
+    private static boolean shows(CustomerFilter filter, Customer customer) {
+        return filter.asPredicate().test(customer);
+    }
+
+    private static CustomerFilter name(String name) {
+        return new CustomerFilter(name, Set.of());
+    }
+
+    @Test
+    void emptyFilterShowsEveryone() {
+        assertTrue(shows(CustomerFilter.NONE, ADA));
+        assertTrue(shows(name("   "), ADA));
+    }
+
+    @Test
+    void everyTermMustAppearInFirstOrLastName() {
+        assertTrue(shows(name("ada aal"), ADA));
+        assertTrue(shows(name("aal ada"), ADA));
+        assertTrue(shows(name("  ada \t aal  "), ADA));
+        assertFalse(shows(name("ada virtanen"), ADA));
+    }
+
+    @Test
+    void termsMayMatchDifferentNames() {
+        assertTrue(shows(name("ada aaltonen"), ADA));
+        assertTrue(shows(name("jarno makinen"), MAKINEN));
+    }
+
+    @Test
+    void matchingIgnoresCase() {
+        assertTrue(shows(name("MAKINEN"), MAKINEN));
+    }
+
+    @Test
+    void matchingIgnoresAccentsInBothDirections() {
+        assertTrue(shows(name("makinen"), MAKINEN));
+        assertTrue(shows(name("mäkinen"), MAKINEN));
+        assertTrue(shows(name("josephine"), JOSEPHINE));
+        assertTrue(shows(name("Joséphine"), JOSEPHINE));
+    }
+
+    @Test
+    void statusFilterKeepsOnlySelectedStatuses() {
+        assertTrue(shows(new CustomerFilter("", Set.of(CustomerStatus.PENDING)), ADA));
+        assertFalse(shows(new CustomerFilter("", Set.of(CustomerStatus.ACTIVE)), ADA));
+        assertTrue(shows(new CustomerFilter("", Set.of(CustomerStatus.ACTIVE, CustomerStatus.PENDING)), ADA));
+    }
+
+    @Test
+    void bothFiltersMustHold() {
+        assertTrue(shows(new CustomerFilter("ada", Set.of(CustomerStatus.PENDING)), ADA));
+        assertFalse(shows(new CustomerFilter("ada", Set.of(CustomerStatus.CLOSED)), ADA));
+        assertFalse(shows(new CustomerFilter("jarno", Set.of(CustomerStatus.PENDING)), ADA));
+    }
+}
