+package com.example.customers.ui;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+
+import java.util.Set;
+
+import com.example.customers.domain.CustomerFilter;
+import com.example.customers.domain.CustomerStatus;
+import com.vaadin.flow.router.QueryParameters;
+import org.junit.jupiter.api.Test;
+
+class CustomerListViewUrlTest {
+
+    @Test
+    void readsNameAndStatusFromTheAddress() {
+        CustomerFilter filter = CustomerListView.filterFrom(
+                QueryParameters.fromString("name=vir&status=CLOSED,ACTIVE"));
+
+        assertEquals("vir", filter.name());
+        assertEquals(Set.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED), filter.statuses());
+    }
+
+    @Test
+    void missingParametersMeanAnEmptyFilter() {
+        assertEquals(CustomerFilter.NONE, CustomerListView.filterFrom(QueryParameters.empty()));
+    }
+
+    @Test
+    void unrecognisedStatusNamesAreIgnored() {
+        CustomerFilter filter = CustomerListView.filterFrom(QueryParameters.fromString("status=ACTIVE,bogus,"));
+
+        assertEquals(Set.of(CustomerStatus.ACTIVE), filter.statuses());
+    }
+
+    @Test
+    void writesStatusesInDeclarationOrder() {
+        CustomerFilter filter = new CustomerFilter("vir", Set.of(CustomerStatus.CLOSED, CustomerStatus.ACTIVE));
+
+        assertEquals("name=vir&status=ACTIVE,CLOSED", CustomerListView.toQueryString(filter));
+    }
+
+    @Test
+    void anEmptyFilterWritesNoParameters() {
+        assertEquals("", CustomerListView.toQueryString(CustomerFilter.NONE));
+        assertEquals("", CustomerListView.toQueryString(new CustomerFilter("  ", Set.of())));
+    }
+
+    @Test
+    void theFilterSurvivesAWriteAndRead() {
+        CustomerFilter filter = new CustomerFilter("mäkinen ada & co",
+                Set.of(CustomerStatus.PENDING, CustomerStatus.ACTIVE));
+
+        String written = CustomerListView.toQueryString(filter);
+
+        assertEquals(filter, CustomerListView.filterFrom(QueryParameters.fromString(written)));
+    }
+}
